const HIVE_DETAIL_HERO_PHOTOS=[
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,"
];

function hiveDetailHeroPhoto(h){
  const s=state();
  const idx=Math.max(0,s.hives.findIndex(x=>x.id===h.id));
  return HIVE_DETAIL_HERO_PHOTOS[idx%HIVE_DETAIL_HERO_PHOTOS.length];
}


function hivePhotos(h){
  return Array.isArray(h.photos)?h.photos:[];
}

function compressHivePhoto(file,maxSide=800,quality=.66){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=()=>reject(new Error('Unable to read photo'));
    reader.onload=()=>{
      const img=new Image();
      img.onerror=()=>reject(new Error('Unsupported image'));
      img.onload=()=>{
        const scale=Math.min(1,maxSide/Math.max(img.width,img.height));
        const w=Math.max(1,Math.round(img.width*scale));
        const h=Math.max(1,Math.round(img.height*scale));
        const canvas=document.createElement('canvas');
        canvas.width=w;canvas.height=h;
        const ctx=canvas.getContext('2d');
        ctx.drawImage(img,0,0,w,h);
        resolve(canvas.toDataURL('image/jpeg',quality));
      };
      img.src=reader.result;
    };
    reader.readAsDataURL(file);
  });
}

async function addHivePhotos(hiveId,input){
  const files=[...(input?.files||[])];
  if(!files.length)return;
  const s=state(),h=hive(s,hiveId);
  if(!h)return;
  h.photos=Array.isArray(h.photos)?h.photos:[];
  const room=Math.max(0,12-h.photos.length);
  if(!room){toast('Maximum 12 photos per hive');input.value='';return}

  try{
    for(const file of files.slice(0,room)){
      if(!file.type.startsWith('image/'))continue;
      const data=await compressHivePhoto(file);
      h.photos.push({id:'p'+Date.now()+Math.random().toString(36).slice(2,6),data,date:new Date().toISOString().slice(0,10)});
    }
    if(save(s)!==false){
      toast('Photo added');
      render();
    }
  }catch(err){
    console.error(err);
    toast('Could not add photo');
  }
  input.value='';
}

